import Foundation

/// 과학 개념 사전 보충: 초등 단원, 고등 통합과학·물리학·화학
extension DoitCurriculum {
    static let scienceMore: [CurriculumEntry] = [
        // MARK: - 초등
        ce(.elementary, "소리의 성질", ["소리의 발생", "떨림"], "소리는 물체가 떨릴 때 나요. 소리가 나는 물체에 손을 대 보면 떨림을 느낄 수 있고, 떨림을 멈추면 소리도 멈춰요.\n예: 소리가 나는 소리굽쇠를 물에 대면 물이 튀어요."),
        ce(.elementary, "소리의 성질", ["소리의 세기와 높낮이", "큰 소리와 작은 소리", "높은 소리와 낮은 소리"], "소리의 크고 작은 정도를 소리의 세기라고 하는데, 물체가 크게 떨릴수록 큰 소리가 나요. 소리의 높고 낮은 정도는 높낮이라고 하며, 물체가 빠르게 떨릴수록 높은 소리가 나요.\n예: 실로폰은 음판의 길이가 짧을수록 높은 소리가 나요."),
        ce(.elementary, "소리의 성질", ["소리의 전달과 반사", "소리의 전달", "소리의 반사", "메아리"], "소리는 공기 같은 기체뿐 아니라 물 같은 액체, 철이나 나무 같은 고체를 통해서도 전달돼요. 소리는 나아가다가 물체에 부딪치면 되돌아오는데 이것을 소리의 반사라고 해요. 딱딱한 물체는 소리를 잘 반사하고, 부드러운 물체는 소리를 잘 흡수해요.\n예: 산에서 '야호' 하고 외치면 메아리가 들리는 것은 소리의 반사 때문이에요."),
        ce(.elementary, "소리의 성질", ["소음 줄이기", "소음", "방음"], "주변을 시끄럽게 하는 불쾌한 소리를 소음이라고 해요. 방음벽을 세우거나 소리를 흡수하는 물질을 붙이고, 소리가 나는 물체의 떨림을 줄이면 소음을 줄일 수 있어요.\n예: 도로 옆 방음벽과 음악실 벽의 흡음재는 소음을 줄여요."),
        ce(.elementary, "지층과 화석", ["지층", "지층의 생성"], "지층은 자갈, 모래, 진흙 등이 물에 운반되어 차례로 쌓인 뒤 오랜 시간 굳어져 만들어진 층이에요. 지층이 뒤집히지 않았다면 아래에 있는 층이 먼저 쌓인 층이에요. 층마다 알갱이의 크기와 색이 달라서 줄무늬가 보여요.\n예: 바닷가 절벽에서 여러 겹의 줄무늬로 된 지층을 볼 수 있어요."),
        ce(.elementary, "지층과 화석", ["퇴적암의 종류", "이암, 사암, 역암"], "퇴적물이 쌓여 다져지고 굳어져 만들어진 암석을 퇴적암이라고 해요. 알갱이의 크기에 따라 진흙으로 된 이암, 모래로 된 사암, 자갈로 된 역암으로 나눠요.\n예: 역암은 알갱이가 커서 손으로 만지면 거칠고, 이암은 알갱이가 작아 매끄러워요."),
        ce(.elementary, "지층과 화석", ["화석", "fossil", "화석이 만들어지는 과정"], "화석은 아주 오래전에 살았던 생물의 몸체나 생활 흔적이 지층 속에 남아 있는 거예요. 생물의 몸체가 진흙 같은 퇴적물에 빨리 묻히고, 뼈나 껍데기처럼 단단한 부분이 있을 때 화석이 되기 쉬워요.\n예: 삼엽충, 공룡 뼈, 공룡 발자국, 나뭇잎 화석이 있어요."),
        ce(.elementary, "지층과 화석", ["화석으로 알 수 있는 것", "화석의 이용"], "화석을 연구하면 옛날에 살았던 생물의 모습과 생활 방식, 그 지역의 옛날 환경을 알 수 있어요. 또 지층이 쌓인 시기를 짐작할 수 있고, 석탄이나 석유 같은 연료를 찾는 데에도 이용해요.\n예: 산호 화석이 발견된 곳은 옛날에 따뜻하고 얕은 바다였다는 것을 알 수 있어요."),
        ce(.elementary, "화산과 지진", ["화산", "화산 활동", "화산 분출물"], "화산은 땅속 깊은 곳에서 암석이 녹은 마그마가 지표 밖으로 분출하여 생긴 지형이에요. 화산이 분출할 때는 기체인 화산 가스, 액체인 용암, 고체인 화산재와 화산 암석 조각이 나와요.\n예: 우리나라의 한라산과 백두산은 화산이에요."),
        ce(.elementary, "화산과 지진", ["화강암과 현무암 비교", "마그마가 식어 만들어진 암석"], "마그마가 식어서 만들어진 암석 중 화강암은 땅속 깊은 곳에서 천천히 식어 알갱이가 크고 밝은색이에요. 현무암은 지표 가까이에서 빨리 식어 알갱이가 매우 작고 어두운색이며, 구멍이 뚫려 있는 것도 있어요.\n예: 화강암은 건축 재료로 쓰이고, 현무암은 제주도의 돌담에서 볼 수 있어요."),
        ce(.elementary, "화산과 지진", ["지진", "지진이 일어나는 까닭"], "지진은 지구 내부에서 작용하는 힘이 오랫동안 쌓여 땅이 끊어지면서 흔들리는 현상이에요. 지진의 세기는 규모로 나타내며, 숫자가 클수록 강한 지진이에요.\n예: 규모 5.0인 지진은 규모 3.0인 지진보다 훨씬 강해요."),
        ce(.elementary, "화산과 지진", ["지진 대처 방법", "지진 대피"], "지진으로 흔들릴 때는 튼튼한 탁자 아래로 들어가 머리와 몸을 보호하고, 흔들림이 멈추면 계단을 이용해 넓은 곳으로 대피해요. 엘리베이터는 타지 않고, 건물 밖에서는 건물이나 전봇대에서 멀리 떨어져요.\n예: 학교에서 지진이 나면 책상 아래로 들어가 책상 다리를 꼭 잡아요."),
        ce(.elementary, "물체의 운동", ["물체의 빠르기", "운동하는 물체"], "시간이 지남에 따라 물체의 위치가 변할 때 물체가 운동한다고 해요. 같은 거리를 이동하는 데 걸린 시간이 짧을수록, 같은 시간 동안 이동한 거리가 길수록 빠른 물체예요.\n예: 50m 달리기에서 8초 걸린 친구가 10초 걸린 친구보다 빨라요."),
        ce(.elementary, "물체의 운동", ["속력 구하기", "속력의 단위", "km/h"], "속력은 물체가 단위 시간 동안 이동한 거리로, (속력) = (이동 거리) ÷ (걸린 시간)이에요. 단위는 m/s(미터 매 초), km/h(킬로미터 매 시) 등을 써요.\n예: 자동차가 2시간 동안 160km를 이동했다면 속력은 80km/h예요."),
        ce(.elementary, "물체의 운동", ["교통안전", "속력과 안전"], "속력이 빠를수록 물체를 멈추는 데 더 긴 거리가 필요해서 사고가 나면 더 위험해요. 그래서 학교 앞 어린이 보호 구역에서는 자동차의 속력을 제한하고, 과속 방지 턱을 설치해요.\n예: 어린이 보호 구역의 제한 속도는 보통 30km/h예요."),
        ce(.elementary, "생물과 우리 생활", ["균류", "곰팡이와 버섯"], "곰팡이와 버섯 같은 균류는 몸 전체가 가는 실 모양의 균사로 이루어져 있고, 대부분 포자로 번식해요. 스스로 양분을 만들지 못해서 다른 생물이나 죽은 생물에서 양분을 얻어요.\n예: 빵에 핀 검은빵곰팡이, 표고버섯, 느타리버섯은 균류예요."),
        ce(.elementary, "생물과 우리 생활", ["원생생물", "짚신벌레와 해캄"], "원생생물은 동물, 식물, 균류로 분류되지 않으며 생김새가 단순한 생물이에요. 주로 논, 연못처럼 물이 고인 곳이나 물살이 느린 곳에 살아요.\n예: 짚신벌레, 아메바, 해캄, 반달말은 원생생물이에요."),
        ce(.elementary, "생물과 우리 생활", ["세균", "세균의 특징"], "세균은 균류나 원생생물보다 크기가 매우 작아 맨눈으로 볼 수 없고, 모양에 따라 공 모양, 막대 모양, 나선 모양 등이 있어요. 땅, 물, 공기, 생물의 몸 등 거의 모든 곳에 살고, 조건이 맞으면 짧은 시간에 많은 수로 늘어나요.\n예: 대장균, 젖산균, 포도상 구균은 세균이에요."),
        ce(.elementary, "생물과 우리 생활", ["첨단 생명 과학", "생물이 우리 생활에 미치는 영향"], "균류와 세균은 죽은 생물을 분해해 환경을 깨끗하게 하고, 된장, 김치, 요구르트 같은 발효 식품을 만드는 데 이용돼요. 반면 음식을 상하게 하거나 질병을 일으키기도 해요. 생물의 특성을 이용해 생활에 활용하는 기술을 첨단 생명 과학이라고 해요.\n예: 푸른곰팡이에서 얻은 물질로 세균을 죽이는 항생제인 페니실린을 만들었어요."),
        ce(.elementary, "식물의 구조와 기능", ["뿌리의 기능", "뿌리털"], "뿌리는 땅속으로 뻗어 식물을 지지하고, 뿌리털을 통해 물과 양분을 흡수해요. 고구마나 무처럼 양분을 저장하는 뿌리도 있어요.\n예: 뿌리털은 뿌리의 표면적을 넓혀 물을 더 잘 흡수하게 해요."),
        ce(.elementary, "식물의 구조와 기능", ["줄기의 기능", "물이 이동하는 통로"], "줄기는 식물을 지지하고, 뿌리에서 흡수한 물이 잎까지 이동하는 통로 역할을 해요. 감자처럼 양분을 저장하는 줄기도 있어요.\n예: 붉은 색소를 탄 물에 백합 줄기를 꽂아 두면 줄기 속 물이 이동하는 길이 붉게 물들어요."),
        ce(.elementary, "식물의 구조와 기능", ["잎이 하는 일", "잎에서 만든 양분", "잎의 기공"], "잎은 빛과 물, 이산화 탄소를 이용해 녹말 같은 양분을 만드는데, 이것을 광합성이라고 해요. 또 뿌리에서 올라온 물이 잎의 기공을 통해 수증기로 빠져나가는 증산 작용이 일어나요.\n예: 빛을 받은 잎에 아이오딘-아이오딘화 칼륨 용액을 떨어뜨리면 청람색으로 변해 녹말이 있음을 알 수 있어요."),
        ce(.elementary, "식물의 구조와 기능", ["꽃과 열매의 기능", "씨가 퍼지는 방법", "꽃가루받이와 열매"], "꽃은 꽃가루받이(수분)를 거쳐 씨를 만드는 일을 해요. 꽃가루받이는 곤충, 새, 바람, 물 등의 도움을 받아 이루어지고, 씨가 자라면서 씨를 싸고 있는 부분이 열매가 돼요. 씨는 바람에 날리거나, 동물의 털에 붙거나, 동물에게 먹히는 등 여러 방법으로 퍼져요.\n예: 민들레 씨는 바람에, 도깨비바늘 씨는 동물의 털에 붙어서 퍼져요."),
        ce(.elementary, "연소와 소화", ["연소", "연소의 조건", "발화점"], "물질이 산소와 빠르게 반응하면서 빛과 열을 내는 현상을 연소라고 해요. 연소가 일어나려면 탈 물질, 산소, 발화점 이상의 온도라는 세 가지 조건이 모두 필요해요. 불을 직접 붙이지 않아도 물질이 타기 시작하는 온도를 발화점이라고 해요.\n예: 성냥 머리를 철판 위에 놓고 가열하면 불을 붙이지 않아도 불이 붙어요."),
        ce(.elementary, "연소와 소화", ["연소 후 생기는 물질", "연소 생성물"], "초나 나무 같은 물질이 연소하면 물과 이산화 탄소가 생겨요. 푸른색 염화 코발트 종이가 붉게 변하면 물이, 석회수가 뿌옇게 흐려지면 이산화 탄소가 생긴 거예요.\n예: 초가 타는 집기병 안쪽 벽에 물방울이 맺혀요."),
        ce(.elementary, "연소와 소화", ["소화", "불을 끄는 방법"], "연소의 조건 중 한 가지 이상을 없애 불을 끄는 것을 소화라고 해요. 탈 물질을 없애거나, 산소 공급을 막거나, 온도를 발화점 아래로 낮추면 불이 꺼져요.\n예: 알코올램프 뚜껑을 덮으면 산소가 차단되고, 물을 뿌리면 온도가 낮아져 불이 꺼져요."),
        ce(.elementary, "연소와 소화", ["화재 안전", "화재 대피 방법", "소화기 사용법"], "불이 나면 '불이야!' 하고 크게 외쳐 주변에 알리고 119에 신고해요. 연기가 많으면 젖은 수건으로 코와 입을 막고 몸을 낮추어 계단으로 대피해요. 소화기는 안전핀을 뽑고 바람을 등진 채 노즐을 불 쪽으로 향하게 한 뒤 손잡이를 움켜쥐어 사용해요.\n예: 화재 때는 엘리베이터를 타지 않아요."),
        ce(.elementary, "여러 가지 기체", ["산소", "산소의 성질"], "산소는 색깔과 냄새가 없고, 스스로 타지 않지만 다른 물질이 잘 타도록 도와요. 생물의 호흡에 필요하고, 철 같은 금속을 녹슬게 해요. 묽은 과산화 수소수를 이산화 망가니즈에 떨어뜨리면 산소가 발생해요.\n예: 산소가 든 집기병에 향불을 넣으면 불꽃이 더 커져요."),
        ce(.elementary, "여러 가지 기체", ["이산화 탄소", "이산화 탄소의 성질"], "이산화 탄소는 색깔과 냄새가 없고, 물질이 타지 못하게 막으며, 석회수를 뿌옇게 흐리게 해요. 진한 식초나 묽은 염산을 탄산 칼슘(대리석, 조개껍데기)에 떨어뜨리면 이산화 탄소가 발생해요.\n예: 이산화 탄소는 소화기, 탄산음료, 드라이아이스에 이용돼요."),
        ce(.elementary, "여러 가지 기체", ["온도와 압력에 따른 기체의 부피", "압력과 기체의 부피", "온도와 기체의 부피"], "기체에 압력을 가하면 부피가 작아지고, 압력을 줄이면 부피가 커져요. 또 기체는 온도가 높아지면 부피가 커지고 온도가 낮아지면 부피가 작아져요.\n예: 비행기를 타고 높이 올라가면 과자 봉지가 부풀고, 찌그러진 탁구공을 뜨거운 물에 넣으면 펴져요."),
        ce(.elementary, "여러 가지 기체", ["공기를 이루는 기체", "질소"], "공기는 여러 가지 기체가 섞여 있는 혼합물로, 질소가 약 78%, 산소가 약 21%를 차지하고 나머지는 아르곤, 이산화 탄소 등이에요. 질소는 과자 봉지에 넣어 내용물이 상하지 않게 하는 데 이용해요.\n예: 네온은 광고용 조명에, 헬륨은 풍선과 비행선에 이용해요."),

        // MARK: - 고등 (통합과학)
        ce(.high, "과학의 기초", ["기본량", "기본 단위", "SI 단위", "유도량"], "물리량 중 다른 물리량을 기준으로 정하지 않고 독립적으로 정한 7가지를 기본량이라고 해요. 기본량과 단위는 길이(m), 질량(kg), 시간(s), 전류(A), 온도(K), 물질량(mol), 광도(cd)예요. 기본량을 조합해 나타내는 속력(m/s), 밀도(kg/m³), 힘(N) 같은 물리량은 유도량이라고 해요.\n예: 넓이는 길이 × 길이이므로 단위가 m²인 유도량이에요."),
        ce(.high, "과학의 기초", ["측정과 어림", "측정 표준", "어림"], "측정은 어떤 양을 기준이 되는 단위와 비교하여 수치로 나타내는 것이고, 국제적으로 정한 측정의 기준을 측정 표준이라고 해요. 측정값에는 항상 오차가 있어서 여러 번 측정해 평균을 구해요. 직접 재기 어려운 양은 알고 있는 값을 이용해 어림하기도 해요.\n예: 종이 한 장의 두께는 100장의 두께를 재서 100으로 나누어 어림할 수 있어요."),
        ce(.high, "과학의 기초", ["디지털 정보", "아날로그 신호와 디지털 신호", "비트"], "소리, 빛, 온도처럼 연속적으로 변하는 정보는 아날로그 신호예요. 이를 센서로 측정하고 0과 1의 조합인 디지털 신호로 바꾸면 저장, 처리, 전송이 쉽고 잡음에 강해요. 디지털 정보의 기본 단위는 비트(bit)이고, 8비트는 1바이트예요.\n예: n비트로는 2ⁿ가지 정보를 나타낼 수 있어서 3비트로 8가지를 표현할 수 있어요."),
        ce(.high, "과학의 기초", ["센서", "자연 현상의 측정과 센서"], "센서는 온도, 빛, 소리, 압력 같은 자연의 변화를 감지하여 전기 신호로 바꾸어 주는 장치예요. 센서로 측정한 정보는 디지털 신호로 바뀌어 스마트 기기 등에서 처리되고 활용돼요.\n예: 스마트폰은 조도 센서로 주변 밝기를 감지해 화면 밝기를 조절해요."),
        ce(.high, "원소의 생성", ["우주 초기의 원소 생성", "수소와 헬륨의 생성", "기본 입자"], "빅뱅 직후 우주에서는 쿼크와 전자 같은 기본 입자가 생겨났고, 쿼크가 결합해 양성자와 중성자가 만들어졌어요. 빅뱅 후 약 3분 무렵 양성자와 중성자가 결합해 헬륨 원자핵이 만들어졌고, 약 38만 년 후 원자핵이 전자와 결합해 수소와 헬륨 원자가 생성됐어요. 이때 수소와 헬륨의 질량비는 약 3 : 1이에요.\n예: 우주 배경 복사는 원자가 생성되며 빛이 자유롭게 퍼져 나간 흔적이에요."),
        ce(.high, "원소의 생성", ["별에서의 원소 생성", "별의 핵융합", "초신성 폭발"], "별의 중심에서는 수소 핵융합으로 헬륨이 만들어지고, 질량이 큰 별에서는 핵융합이 계속되어 탄소, 산소, 규소 등을 거쳐 철까지 만들어져요. 철보다 무거운 원소는 질량이 매우 큰 별이 일생의 마지막에 일으키는 초신성 폭발 같은 과정에서 만들어져 우주 공간으로 퍼져요.\n예: 우리 몸과 지구를 이루는 탄소, 산소, 철 같은 원소는 별 내부에서 만들어졌어요."),
        ce(.high, "원소의 생성", ["스펙트럼", "연속 스펙트럼", "흡수 스펙트럼", "방출 스펙트럼"], "빛을 분광기로 파장에 따라 나눈 것을 스펙트럼이라고 해요. 백열등 빛처럼 모든 색이 연속으로 나타나면 연속 스펙트럼, 고온의 기체에서 특정 파장의 빛만 밝은 선으로 나타나면 방출 스펙트럼, 연속 스펙트럼 중 특정 파장이 저온의 기체에 흡수되어 검은 선으로 나타나면 흡수 스펙트럼이에요. 원소마다 선의 위치가 다르므로 별빛의 스펙트럼으로 별을 이루는 원소를 알 수 있어요.\n예: 태양 스펙트럼의 흡수선을 분석해 태양이 주로 수소와 헬륨으로 이루어졌음을 알아냈어요."),
        ce(.high, "원소의 생성", ["태양계와 지구의 형성", "원시 태양계 성운"], "약 46억 년 전 성운이 중력으로 수축하며 회전하여 원반 모양의 원시 태양계 성운이 되었어요. 중심부에서는 원시 태양이 만들어지고, 원반에서는 미행성체가 충돌하고 뭉쳐 행성이 되었어요. 원시 지구는 마그마 바다 상태를 거치며 무거운 철과 니켈은 중심으로 가라앉아 핵이 되고 가벼운 물질은 맨틀을 이루었어요.\n예: 태양에 가까운 곳에서는 녹는점이 높은 암석과 금속 성분이 남아 지구형 행성이 만들어졌어요."),
        ce(.high, "자연의 구성 물질", ["규산염 광물", "규산염 사면체"], "지각을 이루는 광물의 대부분은 규소와 산소를 기본으로 하는 규산염 광물이에요. 규소 1개를 중심으로 산소 4개가 정사면체 모양으로 결합한 규산염 사면체가 기본 단위이고, 사면체가 결합하는 방식에 따라 독립형(감람석), 단사슬(휘석), 복사슬(각섬석), 판상(흑운모), 망상(석영, 장석) 구조가 돼요.\n예: 흑운모는 판상 구조라서 얇게 한 방향으로 쪼개져요."),
        ce(.high, "자연의 구성 물질", ["단백질", "아미노산", "펩타이드 결합"], "단백질은 생명체를 구성하고 효소, 호르몬, 항체 등으로 생명 활동을 조절하는 물질이에요. 기본 단위는 아미노산이고, 아미노산끼리 펩타이드 결합으로 길게 연결된 뒤 접히고 구부러져 고유한 입체 구조를 가져요. 단백질의 기능은 이 입체 구조에 따라 달라져요.\n예: 생명체의 단백질을 이루는 아미노산은 20종류예요."),
        ce(.high, "자연의 구성 물질", ["핵산", "DNA와 RNA", "뉴클레오타이드"], "핵산은 유전 정보를 저장하고 전달하는 물질로 DNA와 RNA가 있어요. 기본 단위는 인산, 당, 염기가 1 : 1 : 1로 결합한 뉴클레오타이드예요. DNA는 두 가닥이 꼬인 이중 나선 구조이고 염기로 A, G, C, T를, RNA는 한 가닥이고 A, G, C, U를 가져요.\n예: DNA에서 A는 T와, G는 C와 상보적으로 결합해요."),
        ce(.high, "자연의 구성 물질", ["탄소 화합물", "탄소 골격"], "탄소 원자는 최대 4개의 다른 원자와 공유 결합할 수 있어서 사슬, 가지, 고리 모양 등 다양한 구조의 화합물을 만들어요. 생명체를 이루는 탄수화물, 지질, 단백질, 핵산은 모두 탄소를 기본 골격으로 하는 탄소 화합물이에요.\n예: 메테인(CH₄), 에탄올(C₂H₅OH), 포도당(C₆H₁₂O₆)은 탄소 화합물이에요."),
        ce(.high, "신소재의 개발과 이용", ["반도체", "semiconductor", "도핑"], "반도체는 전기 전도성이 도체와 절연체의 중간인 물질로, 순수한 규소나 저마늄에 소량의 불순물을 첨가(도핑)하면 전기 전도성이 크게 높아져요. p형 반도체와 n형 반도체를 접합하여 다이오드, 트랜지스터, 발광 다이오드(LED) 등을 만들어요.\n예: 다이오드는 전류를 한쪽 방향으로만 흐르게 해서 교류를 직류로 바꾸는 데 쓰여요."),
        ce(.high, "신소재의 개발과 이용", ["초전도체", "초전도 현상", "마이스너 효과"], "초전도체는 특정 온도 이하에서 전기 저항이 0이 되는 물질이에요. 저항이 0이므로 큰 전류가 흘러도 열이 발생하지 않아 에너지 손실이 없고, 외부 자기장을 밀어내는 마이스너 효과가 나타나요.\n예: 초전도 자석은 자기 공명 영상(MRI) 장치와 자기 부상 열차에 쓰여요."),
        ce(.high, "신소재의 개발과 이용", ["그래핀과 탄소 나노 튜브", "그래핀", "탄소 나노 튜브", "풀러렌"], "그래핀은 탄소 원자가 육각형 벌집 모양으로 결합한 한 층의 얇은 막으로, 강도가 매우 크고 전기 전도성이 좋으며 투명하고 잘 휘어져요. 탄소 나노 튜브는 그래핀을 원통 모양으로 만든 구조이고, 풀러렌은 탄소 원자 60개가 축구공 모양으로 결합한 구조예요.\n예: 그래핀은 휘어지는 디스플레이나 터치스크린 소재로 연구되고 있어요."),
        ce(.high, "신소재의 개발과 이용", ["자성 물질", "강자성체", "네오디뮴 자석"], "물질이 자기장 안에서 자석의 성질을 띠는 것을 자성이라고 해요. 철, 니켈, 코발트처럼 자기장 안에서 강하게 자기화되고 외부 자기장을 없애도 자성이 오래 유지될 수 있는 물질을 강자성체라 하고, 이를 이용해 강한 자석과 정보 저장 장치를 만들어요.\n예: 네오디뮴 자석은 크기가 작아도 자기장이 강해서 이어폰 스피커와 전동기에 쓰여요."),
        ce(.high, "지구 시스템", ["지구 시스템의 구성 요소", "지권, 수권, 기권, 생물권, 외권"], "지구 시스템은 지권, 수권, 기권, 생물권, 외권으로 이루어져 있고, 각 권은 서로 영향을 주고받으며 물질과 에너지를 교환해요. 지권은 지각·맨틀·핵, 수권은 바다·빙하·지하수 등 지구의 물, 기권은 대기, 생물권은 지구의 모든 생물, 외권은 기권 밖의 우주 공간이에요.\n예: 화산 활동으로 지권의 기체가 기권으로 방출되는 것은 지권과 기권의 상호 작용이에요."),
        ce(.high, "지구 시스템", ["지구 시스템의 에너지원", "태양 에너지", "지구 내부 에너지", "조력 에너지"], "지구 시스템을 움직이는 에너지원은 태양 에너지, 지구 내부 에너지, 조력 에너지예요. 태양 에너지는 양이 가장 많고 대기와 해수의 순환, 물의 순환, 광합성을 일으켜요. 지구 내부 에너지는 판의 운동, 화산과 지진을 일으키고, 조력 에너지는 달과 태양의 인력으로 밀물과 썰물을 일으켜요.\n예: 바람과 해류는 태양 에너지, 지진은 지구 내부 에너지 때문에 생겨요."),
        ce(.high, "지구 시스템", ["물의 순환", "물의 순환과 에너지 이동"], "지구의 물은 증발, 응결, 강수, 지표수와 지하수의 흐름을 통해 수권, 기권, 지권, 생물권을 끊임없이 순환해요. 물의 순환을 일으키는 주된 에너지원은 태양 에너지이고, 순환 과정에서 에너지가 함께 이동하며 지표의 모습을 바꿔요.\n예: 바다에서 증발한 수증기가 육지에 비로 내려 강을 따라 다시 바다로 흘러가요."),
        ce(.high, "지구 시스템", ["탄소의 순환", "지구 시스템의 탄소 순환"], "탄소는 대기 중 이산화 탄소, 생물체의 유기물, 해수에 녹은 탄산 이온, 석회암과 화석 연료 등의 형태로 각 권 사이를 순환해요. 광합성은 기권의 탄소를 생물권으로, 호흡과 연소는 탄소를 기권으로 돌려보내요. 화석 연료를 많이 사용하면 지권에 저장되어 있던 탄소가 빠르게 기권으로 이동해 대기 중 이산화 탄소 농도가 높아져요.\n예: 바다에 녹은 이산화 탄소는 산호나 조개껍데기의 탄산 칼슘이 되어 석회암으로 쌓이기도 해요."),
        ce(.high, "생태계와 환경", ["생태계의 구성 요소", "생물적 요인", "비생물적 요인"], "생태계는 생물적 요인과 비생물적 요인으로 이루어지고, 이들은 서로 영향을 주고받아요. 생물적 요인은 생산자, 소비자, 분해자로 나뉘고, 비생물적 요인에는 빛, 온도, 물, 공기, 토양 등이 있어요.\n예: 낙엽이 분해자에 의해 분해되어 토양이 비옥해지는 것은 생물적 요인이 비생물적 요인에 영향을 준 예예요."),
        ce(.high, "생태계와 환경", ["생물과 환경의 상호 작용", "빛과 생물", "온도와 생물"], "생물은 빛, 온도, 물 같은 환경에 적응하여 살아가요. 빛의 세기에 따라 양지 식물과 음지 식물이 나뉘고, 일조 시간은 꽃 피는 시기에 영향을 줘요. 추운 지방의 포유류는 몸집이 크고 귀 같은 말단부가 작아 열 손실을 줄여요.\n예: 사막여우는 귀가 커서 열을 잘 방출하고, 북극여우는 귀가 작아요."),
        ce(.high, "생태계와 환경", ["생태 피라미드", "에너지 피라미드", "먹이 그물"], "생태계에서 먹이 사슬이 복잡하게 얽힌 것을 먹이 그물이라고 해요. 각 영양 단계의 개체 수, 생물량, 에너지양을 아래에서부터 차례로 쌓으면 대체로 피라미드 모양이 되는데, 이것을 생태 피라미드라고 해요. 에너지는 상위 영양 단계로 갈수록 호흡과 열로 많이 빠져나가 줄어들어요.\n예: 생산자 → 1차 소비자 → 2차 소비자로 갈수록 이용할 수 있는 에너지양이 줄어요."),
        ce(.high, "생태계와 환경", ["생태계 평형과 환경 변화", "생태계 평형의 회복"], "안정된 생태계는 먹이 그물이 복잡해서 어떤 생물이 일시적으로 줄거나 늘어도 시간이 지나면 원래 상태로 회복되는데, 이것을 생태계 평형이라고 해요. 그러나 서식지 파괴, 외래종 유입, 지구 온난화 같은 큰 환경 변화는 생태계 평형을 깨뜨릴 수 있어요.\n예: 1차 소비자가 갑자기 늘면 생산자는 줄고 2차 소비자는 늘었다가, 시간이 지나면 다시 평형을 되찾아요."),
        ce(.high, "기후 변화와 에너지", ["지구 온난화와 기후 변화", "기후 변화의 영향"], "대기 중 이산화 탄소, 메테인 같은 온실 기체가 늘어나 온실 효과가 강해지면서 지구의 평균 기온이 높아지는 것을 지구 온난화라고 해요. 지구 온난화로 빙하가 녹고 해수면이 상승하며, 폭염, 가뭄, 집중 호우 같은 기상 이변이 잦아지고 생물의 분포가 변해요.\n예: 우리나라에서 사과 재배지가 점점 북쪽으로 옮겨 가고 있어요."),
        ce(.high, "기후 변화와 에너지", ["에너지 전환과 효율", "열효율"], "에너지가 전환될 때 공급한 에너지 중 유용하게 쓰인 에너지의 비율을 에너지 효율이라고 해요. 에너지 효율(%) = (유용하게 쓰인 에너지 ÷ 공급한 에너지) × 100이고, 전환 과정에서 일부는 열로 빠져나가므로 효율은 100%보다 작아요.\n예: 100J의 전기 에너지를 공급한 전구에서 빛에너지가 20J이면 효율은 20%예요."),
        ce(.high, "기후 변화와 에너지", ["화석 연료", "석탄, 석유, 천연가스"], "화석 연료는 오래전 생물의 유해가 땅속에 묻혀 높은 열과 압력을 받아 만들어진 석탄, 석유, 천연가스 같은 연료예요. 에너지를 많이 얻을 수 있지만 매장량이 한정되어 있고, 연소할 때 이산화 탄소와 대기 오염 물질이 나와요.\n예: 화력 발전소는 화석 연료를 태운 열로 증기를 만들어 터빈을 돌려요."),
        ce(.high, "기후 변화와 에너지", ["탄소 중립", "넷 제로", "파리 협정"], "탄소 중립은 인간 활동으로 배출하는 온실 기체의 양과 흡수·제거하는 양을 같게 하여 실질적인 배출량을 0으로 만드는 거예요. 신재생 에너지 사용, 에너지 효율 향상, 숲 가꾸기, 탄소 포집 기술 등이 탄소 중립을 위한 방법이에요.\n예: 2015년 파리 협정에서 여러 나라는 지구 평균 기온 상승을 산업화 이전 대비 2°C보다 훨씬 낮게 유지하기로 했어요."),
        ce(.high, "발전과 신재생 에너지", ["발전기", "발전기의 원리"], "발전기는 자석 사이에서 코일을 회전시키거나 코일 근처에서 자석을 회전시켜 전자기 유도로 전기를 만드는 장치예요. 이때 운동 에너지가 전기 에너지로 전환돼요. 화력, 원자력, 수력, 풍력 발전은 모두 터빈을 돌려 발전기를 작동시킨다는 공통점이 있어요.\n예: 자전거 바퀴의 회전으로 전조등을 켜는 장치도 작은 발전기예요."),
        ce(.high, "발전과 신재생 에너지", ["전력 수송", "송전", "변압기", "손실 전력"], "발전소에서 만든 전기는 송전선을 통해 멀리 보내는데, 송전선의 저항 때문에 열로 손실되는 전력은 전류의 제곱에 비례해요(P = I²R). 같은 전력을 보낼 때 전압을 높이면 전류가 작아지므로 손실을 줄일 수 있어서, 변압기로 전압을 높여 송전하고 사용하는 곳 근처에서 다시 낮춰요.\n예: 송전 전압을 2배로 높이면 전류는 1/2배, 손실 전력은 1/4배가 돼요."),
        ce(.high, "발전과 신재생 에너지", ["태양광 발전과 풍력 발전", "태양 전지", "풍력 발전"], "태양광 발전은 태양 전지에서 빛에너지를 전기 에너지로 직접 바꾸고, 풍력 발전은 바람의 운동 에너지로 날개를 돌려 발전기를 작동시켜요. 둘 다 연료가 필요 없고 발전 중 온실 기체를 거의 배출하지 않지만, 날씨와 시간에 따라 발전량이 달라지는 단점이 있어요.\n예: 태양 전지는 p형 반도체와 n형 반도체를 접합해 만들어요."),
        ce(.high, "발전과 신재생 에너지", ["핵발전", "원자력 발전", "핵분열"], "핵발전(원자력 발전)은 우라늄 같은 무거운 원자핵이 쪼개지는 핵분열에서 나오는 에너지로 물을 끓여 터빈을 돌려요. 적은 연료로 많은 에너지를 얻고 온실 기체 배출이 적지만, 방사성 폐기물 처리와 안전 관리가 중요해요.\n예: 핵분열 전후 줄어든 질량이 E = mc²에 따라 에너지로 바뀌어요."),
        ce(.high, "발전과 신재생 에너지", ["연료 전지", "수소 연료 전지"], "연료 전지는 수소와 산소가 반응하여 물이 생성될 때 나오는 화학 에너지를 전기 에너지로 직접 바꾸는 장치예요. 발전 과정에서 물만 생성되어 환경 오염이 적고 효율이 높지만, 수소를 생산하고 저장하는 비용이 커요.\n예: 수소 자동차는 연료 전지로 만든 전기로 전동기를 돌려요."),

        // MARK: - 고등 (물리학 · 화학)
        ce(.high, "파동과 정보 통신", ["전자기파의 종류", "전자기파", "전자기파 스펙트럼"], "전자기파는 전기장과 자기장이 진동하며 퍼져 나가는 파동으로, 진공에서도 빛의 속력으로 전달돼요. 파장이 짧은 것부터 감마선, X선, 자외선, 가시광선, 적외선, 마이크로파, 라디오파로 나뉘고, 파장에 따라 쓰임새가 달라요.\n예: X선은 뼈 사진 촬영에, 적외선은 열화상 카메라와 리모컨에, 마이크로파는 전자레인지와 통신에 쓰여요."),
        ce(.high, "파동과 정보 통신", ["빛의 이중성", "물질파", "드브로이 파장"], "빛은 간섭과 회절처럼 파동의 성질을 보이고, 광전 효과처럼 입자(광자)의 성질도 보이는데 이를 빛의 이중성이라고 해요. 드브로이는 전자 같은 입자도 파동의 성질을 가진다고 제안했고, 이를 물질파라고 해요. 물질파의 파장은 λ = h/(mv)예요.\n예: 전자 현미경은 전자의 물질파를 이용해 광학 현미경보다 훨씬 작은 물체를 볼 수 있어요."),
        ce(.high, "화학의 첫걸음", ["화학의 유용성", "하버의 암모니아 합성"], "화학은 인류의 식량, 의류, 주거 문제를 해결하는 데 크게 기여했어요. 하버는 공기 중의 질소와 수소를 반응시켜 암모니아를 대량으로 합성하는 방법을 개발했고, 이를 원료로 만든 질소 비료가 식량 생산을 크게 늘렸어요. 나일론 같은 합성 섬유와 시멘트, 철근 콘크리트 같은 건축 재료도 화학의 발전으로 널리 쓰이게 되었어요.\n예: N₂ + 3H₂ → 2NH₃"),
        ce(.high, "화학의 첫걸음", ["몰 농도", "molarity"], "몰 농도는 용액 1L에 녹아 있는 용질의 양(mol)으로 나타낸 농도이고, 단위는 M 또는 mol/L예요. 몰 농도(M) = 용질의 양(mol) ÷ 용액의 부피(L)예요.\n예: NaOH 0.2mol을 물에 녹여 용액 500mL를 만들면 몰 농도는 0.2 ÷ 0.5 = 0.4M이에요."),
        ce(.high, "화학의 첫걸음", ["탄소 화합물의 유용성", "메테인", "에탄올", "아세트산"], "탄소 화합물은 연료, 의약품, 플라스틱 등 생활 곳곳에 쓰여요. 메테인(CH₄)은 액화 천연가스(LNG)의 주성분이고, 에탄올(C₂H₅OH)은 소독용 알코올과 연료로, 아세트산(CH₃COOH)은 식초의 성분으로 쓰여요.\n예: 아세트산 수용액은 산성을 띠어요.")
    ]
}
